// SPDX-License-Identifier: GPL-3.0-only
// Existing scan ordering regression from PR #44, adapted for NIGHTLY scan(true) write lock.
// No real Web MIDI, browser permission, USB, firmware or user-data writes.
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { Script, createContext } from 'node:vm';

const path = process.argv[2] || new URL('./x0x_installer.html', import.meta.url);
const source = readFileSync(path, 'utf8');
const start = source.indexOf('async function scan(allowPostWrite = false) {');
assert.ok(start >= 0, 'production scan function missing');
const end = source.indexOf('\n}', start);
assert.ok(end > start, 'production scan end missing');
const code = source.slice(start, end + 2);
if (source.includes('<html')) {
  assert.match(source.slice(Math.max(0,start-70),start), /let scanSerial = 0;\s*$/,
    'installer must own the scan generation counter');
  assert.match(source, /writing = true;\s*scanSerial\+\+;/,
    'beginning firmware write must invalidate earlier asynchronous scans');
}
assert.match(code, /async function scan\(allowPostWrite = false\) \{/);

function setup() {
  const state = { connected: false, leds: [], changes: [], selected: [], requests: [], closed: [], lookups: [] };
  const ui = { conn: { textContent: '' } };
  const env = {
    $: id => ui[id] || (ui[id] = {}),
    led: value => state.leds.push(value),
    t: k => k,
    midiAccess: async () => ({}),
    Updater: class {
      find(predicate) {
        return new Promise((resolve, reject) => {
          state.requests.push({ predicate, resolve, reject });
        });
      }
    },
    setConnected: (on, detail) => { state.connected = on; state.changes.push({ on, detail }); },
    suggestModel: model => state.selected.push(model),
  };
  const ctx = createContext(env);
  new Script('let writing = false, lastId = null, scanSerial = 0;\n' + code + '\nglobalThis.start=scan; globalThis.setWriting = v => { writing = v; if (v) scanSerial++; }; globalThis.getLastId = () => lastId;').runInContext(ctx);
  const device = (model='SMK-37 Pro') => ({ id: { model, text: model }, name: model + ' MIDI',
    link: { close() { state.closed.push(model); } } });
  const tick = async () => { for (let i=0; i<8; i++) await Promise.resolve(); };
  return { state, ctx, device, tick };
}

async function staleOverwritesWithNotFound() {
  const {state,ctx,device,tick} = setup();
  const first = ctx.start(); await tick(); const second = ctx.start();
  await tick(); assert.equal(state.requests.length, 2);
  state.requests[1].resolve(device()); await second; assert.equal(state.connected,true);
  state.requests[0].resolve(null); await tick();
  // The fixed scan aborts the older request without a redundant loader lookup.
  if (state.requests[2]) state.requests[2].resolve(null);
  await first;
  assert.equal(state.connected,true,'older NOT FOUND scan must not replace newer CONNECTED');
  assert.deepEqual(state.selected,['SMK-37 Pro'],'stale scan must not replace selected model');
  assert.equal(state.requests.length,2,'stale scan should not start redundant OTA scan');
  return 'stale not-found scan cannot replace new connected result';
}
async function staleErrorMustNotOverride() {
  const {state,ctx,device,tick} = setup();
  const first=ctx.start();await tick();const second=ctx.start();
  await tick();
  state.requests[1].resolve(device()); await second;
  state.requests[0].reject(new Error('old unplug error')); await first;
  assert.equal(state.connected,true,'older rejected scan must not overwrite new success');
  assert.equal(state.changes.length,1,'stale error should not modify connection UI');
  return 'stale disconnect error cannot replace new connected result';
}
async function staleWrongModelMustNotOverride() {
  const {state,ctx,device,tick} = setup();
  const first=ctx.start();await tick();const second=ctx.start();
  await tick();
  state.requests[1].resolve(device('SMK-37 Pro')); await second;
  state.requests[0].resolve(device('SMK-37 Elite')); await first;
  assert.deepEqual(state.selected,['SMK-37 Pro'],'older scan must not force wrong model');
  assert.equal(state.closed.length,2,'any stale opened device links must be closed');
  return 'older Elite scan cannot overwrite newer Pro selection';
}
async function writeOverlapsOutstandingScan() {
  const {state,ctx,device,tick} = setup();
  const first=ctx.start();await tick();ctx.setWriting(true);
  state.requests[0].resolve(device());await first;
  assert.equal(state.changes.length,0,'pre-write scan must not alter status after write began');
  assert.equal(state.closed.length,1,'stale discovered device link must close');
  ctx.setWriting(false);
  return 'in-flight scan does not disturb active flashing status';
}
async function latestCanReportNotFoundAndError() {
  for (const mode of ['missing','error','ota']) {
    const {state,ctx,device,tick}=setup();
    const p=ctx.start();await tick();
    if(mode==='error')state.requests[0].reject(new Error('connection denied'));
    else if(mode==='ota') {state.requests[0].resolve(null);await tick();state.requests[1].resolve(device('ota-SMK-37 Elite'));}
    else {state.requests[0].resolve(null);await tick();state.requests[1].resolve(null);}
    await p;
    if(mode==='error')assert.deepEqual(state.changes.map(v=>v.on),[false]);
    if(mode==='missing')assert.deepEqual(state.changes.map(v=>v.on),[false]);
    if(mode==='ota'){assert.equal(state.connected,true);assert.deepEqual(state.selected,['SMK-37 Elite']);}
  }
  return 'latest error, not-found and OTA result still work';
}

async function postwriteScanAllowed() {
  const {state,ctx,device,tick}=setup();
  ctx.setWriting(true);
  const post=ctx.start(true);await tick();
  assert.equal(state.requests.length,1,"post-write scan(true) must run under write lock");
  await ctx.start(); // Blocked user Connect must NOT invalidate post-write rescan.
  state.requests[0].resolve(device());await post;
  assert.equal(state.connected,true);
  assert.equal(state.changes.length,1);
  assert.deepEqual(state.selected, [],
    "postwrite scan must not reload firmware and overwrite saved/restored-slot completion status");
  return 'post-write scan updates connection without clobbering restoration result';
}
async function oldPrewriteCannotReappearAfterWriteEnds() {
  const {state,ctx,device,tick}=setup();
  const first=ctx.start();await tick();
  ctx.setWriting(true);
  ctx.setWriting(false);
  state.requests[0].resolve(device());await first;
  assert.equal(state.changes.length,0,'pre-write scan must stay invalid after write ends');
  assert.equal(state.closed.length,1,'stale pre-write MIDI device must close');
  return 'pre-write scan stays invalid even after permission/write finishes';
}
for (const check of [staleOverwritesWithNotFound,staleErrorMustNotOverride,staleWrongModelMustNotOverride,writeOverlapsOutstandingScan,latestCanReportNotFoundAndError,postwriteScanAllowed,oldPrewriteCannotReappearAfterWriteEnds]) {
  const title=await check();console.log('PASS '+title);
}
console.log('PASS scan-race regression (7 scenarios; NIGHTLY exact source, simulated MIDI)');

// SPDX-License-Identifier: MPL-2.0
/* Copyright (C) 2026 M. Geisler (genkigenki/makkuro)
 *
 * Platform services the controller libraries call: IRQ hookup, critical sections, low-power
 * hooks, delays, clocks, CRC, logging (off), reset. Hardware access goes through ctl_port_*
 * (ctl_port.c). */
#include "ctl_port.h"

/* The SDK uses strcmp for fixed controller names; a small generic implementation keeps the
 * dual-role image inside its flash slot without pulling the toolchain's full libc version. */
int strcmp(const char *a, const char *b)
{
    while (*a && *a == *b) { a++; b++; }
    return (unsigned char)*a - (unsigned char)*b;
}

/* ---- interrupts ---- */
void request_irq(unsigned char index, unsigned char prio, void (*handler)(void), unsigned char cpu_id)
{
    (void)prio; (void)cpu_id;          /* this image runs on core 1: always route to it */
    ctl_port_request_irq(index, CTL_BLE_IRQ_PRIO, handler);
}

static u32 irq_nest, irq_saved;
void local_irq_disable(void) { u32 f = ctl_port_irq_save(); if (irq_nest++ == 0) irq_saved = f; }
void local_irq_enable(void)  { if (irq_nest && --irq_nest == 0) ctl_port_irq_restore(irq_saved); }
void __local_irq_disable(void) { local_irq_disable(); }
void __local_irq_enable(void)  { local_irq_enable(); }
void sys_local_irq_disable(void) { local_irq_disable(); }
void sys_local_irq_enable(void)  { local_irq_enable(); }
int cpu_in_irq(void) { return ctl_port_in_irq(); }
int cpu_irq_disabled(void) { return ctl_port_irq_disabled(); }

/* AES block is used only by this core: a lock is not needed. */
void aes_hw_lock(void) {}
void aes_hw_unlock(void) {}

/* ---- low power: never sleep. low_power_get must return non-null
 *      (felucca-bsp #2 finding). ---- */
static u32 lp_dummy;
void *low_power_get(void *priv, const void *ops) { (void)priv; (void)ops; return &lp_dummy; }
void low_power_put(void *priv) { (void)priv; }
void low_power_on(void) {}
void low_power_request(char *name) { (void)name; }
void low_power_exit_request(void) {}
void low_power_hw_unsleep_lock(void) {}
void low_power_hw_unsleep_unlock(void) {}
s32 low_power_trace_drift(u32 usec) { (void)usec; return 0; }
u8 low_power_get_osc_type(void) { return ctl_bp->osc_type; }
int power_is_poweroff_post(void) { return 0; }

/* ---- clocks and delays (RAM: the RF trim calls them while flash is off) ---- */
/* The radio library (wf_rf_common_init) asks only for "osc": the crystal, 24 MHz on the FM-1 and the
 * SMK-37 (fm1-ctl's shim gives 24 MHz too). Before, "osc" got the system clock (360 MHz): the radio
 * then set its clocks for a wrong crystal, and both cores stopped in the TX IQ trim (watchdog reset). */
#define CTL_OSC_HZ 24000000
int clk_get(const char *name)
{
    if (name && name[0] == 'o') return CTL_OSC_HZ;
    if (name && name[0] == 'l') return (int)ctl_bp->lsb_clk_hz;
    if (name && name[0] == 'h') return (int)ctl_bp->hsb_clk_hz;
    return (int)ctl_bp->sys_clk_hz;
}
/* RAM code: the RF trim calls these while the flash is off. They read the app's free-running
 * counter, so they call nothing and need no calibration. (The app's core 0 feeds the watchdog.) */
static volatile const u32 *dly_tick;
static u32 dly_per_us;
CTL_RAMTEXT void delay_us(unsigned int us)
{
    volatile const u32 *t = dly_tick;
    u32 t0, span = (u32)us * dly_per_us;
    u32 same = 0, last;
    t0 = last = *t;                        /* boot_ok requires tick_addr before ctl_delay_init */
    for (;;) {
        u32 now = *t;
        if ((u32)(now - t0) >= span)
            break;
        if (now != last) {
            last = now;
            same = 0;
        } else if (++same > 1000000u) {   /* the tick counter stopped: count it, go on */
            if (ctl_mb)
                ctl_mb->dbg[XB_DBG_STALL]++;
            break;
        }
    }
}
CTL_RAMTEXT void delay(unsigned int cnt)
{
    for (volatile unsigned int i = cnt; i; i--) {}
}
void ctl_delay_init(void)
{
    dly_tick = (volatile const u32 *)(uintptr_t)ctl_bp->tick_addr;
    dly_per_us = ctl_bp->ticks_per_ms ? ctl_bp->ticks_per_ms / 1000u : 24u;
    if (!dly_per_us) dly_per_us = 1;
}

/* ---- ADC: not wired in this image ---- */
u32 adc_add_sample_ch(u32 ch) { (void)ch; return 0; }
u32 adc_get_value(u32 ch) { (void)ch; return 0; }

/* ---- CRC (software) ---- */
u16 CRC16(const void *ptr, u32 len)
{
    const u8 *p = ptr; u16 crc = 0;     /* CRC-16/XMODEM: poly 0x1021, init 0 */
    while (len--) {
        crc ^= (u16)(*p++) << 8;
        for (int b = 0; b < 8; b++) crc = (crc & 0x8000u) ? (u16)((crc << 1) ^ 0x1021u) : (u16)(crc << 1);
    }
    return crc;
}
u16 crc_get_16bit(const void *ptr, u32 len) { return CRC16(ptr, len); }
u32 crc_get_32bit(const char *src)
{
    u32 crc = 0xFFFFFFFFu;               /* CRC-32 (IEEE) of a NUL-terminated string */
    while (src && *src) {
        crc ^= (u8)*src++;
        for (int b = 0; b < 8; b++) crc = (crc >> 1) ^ (0xEDB88320u & (0u - (crc & 1u)));
    }
    return ~crc;
}

/* ---- WiFi block: not used by this image ---- */
void wlc_main(void) {}

/* ---- logging: off ---- */
void log_print(int level, const char *tag, const char *fmt, ...) { (void)level; (void)tag; (void)fmt; }
int printf(const char *fmt, ...) { (void)fmt; return 0; }
int puts(const char *s) { (void)s; return 0; }
int putchar(int c) { return c; }
void printf_buf(u8 *buf, u32 len) { (void)buf; (void)len; }
void put_buf(const u8 *buf, int len) { (void)buf; (void)len; }
void cpu_assert_debug(void)
{
    if (ctl_mb)                           /* the caller, for DIAG (XB_DBG_INIT_MS is free when init fails) */
        ctl_mb->dbg[XB_DBG_INIT_MS] = (u32)(uintptr_t)__builtin_return_address(0);
    ctl_fail(XB_E_ASSERT);
}

/* ---- reset: the app owns the system. The controller stops; the app goes on without it. ---- */
void P33_SYSTEM_RESET(void)
{
    if (ctl_mb)                           /* the library's caller, for DIAG */
        ctl_mb->dbg[XB_DBG_INIT_MS] = (u32)(uintptr_t)__builtin_return_address(0);
    ctl_fail(XB_E_RESET);
}

// SPDX-License-Identifier: GPL-3.0-only
// Copyright (C) 2026 Leo Kuroshita (@kurogedelic), Hügelton Instruments
//
// Node checks of the web package / OTA helpers (no browser, no hardware). Run from the repo root:
//   node web/test_web.mjs
// The Felucca web editor (web/editor.html) and its protocol harness were retired with the X0X
// fork (commit 23775375); do not restore them here. Remaining checks:
// - fm1pkg.js: productOf and logicalImage on build/felucca.fwsc (skipped without a build)
// - fm1ota.js: a full install and an unplug during the write against a simulated FM-1

import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { execFileSync } from "node:child_process";
import { logicalImage, productOf } from "./fm1pkg.js";
import { Updater, pack7, unpack7 } from "./fm1ota.js";

let failed = 0;
const ok = (cond, what) => { console.log(`${what.padEnd(64)} ${cond ? "ok" : "FAIL"}`); if (!cond) failed++; };
const eq = (a, b) => a.length === b.length && a.every((v, i) => v === b[i]);
const py = (code, ...args) => execFileSync("python3", ["-c", code, ...args], { maxBuffer: 1 << 26 });
const HERE = new URL(".", import.meta.url).pathname;

/* ------------------------------------------------------- packages: JS == Python --- */
async function packages() {
  const pkg = join(HERE, "../build/felucca.fwsc");
  if (!existsSync(pkg)) {
    console.log("packages: skipped (run ./build.sh first)");
    return;
  }
  const raw = readFileSync(pkg);
  const logical = py(`import sys; raw = open(sys.argv[1], "rb").read()
sys.stdout.buffer.write(b"".join(raw[i * 48:i * 48 + 47] for i in range(20)) + raw[960:])`, pkg);
  ok(eq(logicalImage(raw), logical), "fm1pkg.js logicalImage");
  ok(/^FM-1_9\d\d$/.test(productOf(raw)), "fm1pkg.js productOf");
}

/* ------------------------------------------------- update protocol (fm1ota.js) --- */
const HS = [0xF0, 0x00, 0x32, 0x45, 0x00, 0x00, 0x00, 0x40, 0x7F, 0xF7];
const UPGRADE = [0xF0, 0x22, 0x24, 0x35, 0x7F, 0xF7];

/* an FM-1 on WebMIDI: identity, then "device asks, host answers" reads of the image */
class FakeFM1 {
  constructor(image, { unplugAfter = Infinity } = {}) {
    this.image = image; this.unplugAfter = unplugAfter; this.served = 0; this.bad = 0;
    this.access = { inputs: new Map(), outputs: new Map() };
    this.boot("FM-1_015", "FM-1");
  }
  boot(identity, name) {
    this.identity = identity; this.waiting = null; this.queue = [];
    for (const m of [this.access.inputs, this.access.outputs]) { for (const p of m.values()) p.state = "disconnected"; m.clear(); }
    const id = Math.random().toString(36).slice(2);
    this.input = { id: "i" + id, name, state: "connected", onmidimessage: null, open: async () => {} };
    this.output = { id: "o" + id, name, state: "connected", open: async () => {}, send: (d) => {
      if (this.output.state !== "connected") throw new Error("InvalidStateError");
      setTimeout(() => this.rx(Array.from(d)), 1);
    } };
    this.access.inputs.set(this.input.id, this.input);
    this.access.outputs.set(this.output.id, this.output);
  }
  tx(bytes) { const i = this.input; setTimeout(() => { if (i.state === "connected" && i.onmidimessage) i.onmidimessage({ data: Uint8Array.from(bytes) }); }, 1); }
  rx(d) {
    if (eq(d, HS)) {
      const t = [...new TextEncoder().encode(this.identity)];
      const payload = [...t, ...new Array(27 - t.length).fill(0)];
      const body = [0, 0x59, 0x11, 27, 0, 0, ...payload, ~payload.reduce((sum, b) => sum + b, 0) & 255];
      this.tx([0xF0, ...pack7(body), 0xF7]);
    } else if (eq(d, UPGRADE)) {
      this.queue = this.identity.startsWith("ota-")
        ? [...Array.from({ length: 6 }, (_, k) => [k * 512, 512]), [0xF0000000, 8]]
        : [[0, 64], [0x40, 160], [0x1000, 512], [0xE0000000, 8]];
      this.next();
    } else if (this.waiting) {
      const u = unpack7(d.slice(1, -1));
      const [addr, len] = this.waiting;
      const got = u.slice(14, 14 + (addr >= 0xE0000000 ? 8 : len));
      const want = addr >= 0xE0000000 ? [...new TextEncoder().encode("success"), 0] : Array.from(this.image.subarray(addr, addr + len));
      if (!eq(got, want)) this.bad++;
      this.waiting = null;
      this.served++;
      if (this.served >= this.unplugAfter) { this.input.state = this.output.state = "disconnected"; return; }
      if (addr === 0xE0000000) setTimeout(() => this.boot("ota-FM-1_900", "Felucca Update"), 300);
      else if (addr === 0xF0000000) setTimeout(() => this.boot("FM-1_900", "Felucca"), 300);
      else this.next();
    }
  }
  next() {
    const r = this.queue.shift();
    if (!r) return;
    this.waiting = r;
    const [addr, len] = r;
    const u = [0, 0x59, 0x30, 0, 0, 0, 0, addr & 0xFF, (addr >>> 8) & 0xFF, (addr >>> 16) & 0xFF, (addr >>> 24) & 0xFF, len & 0xFF, len >> 8, 0];
    let s = 0;
    for (let i = 6; i < 14; i++) s += u[i];
    u.push(~s & 0xFF);
    this.tx([0xF0, ...pack7(u), 0xF7]);
  }
}

async function updater() {
  const image = Uint8Array.from({ length: 0x2000 }, (_, i) => (i * 7) & 0xFF);
  const dev = new FakeFM1(image);
  const steps = [];
  const got = await new Updater(dev.access).install(image, "FM-1_900", (k) => steps.push(k));
  ok(got === "FM-1_900" && dev.bad === 0 && steps.includes("write") && steps.at(-1) === "done",
    `fm1ota.js: install: running firmware -> loader -> Felucca (${dev.served} reads)`);

  const dev2 = new FakeFM1(image, { unplugAfter: 3 });
  dev2.boot("ota-FM-1_900", "Felucca Update");
  const t0 = Date.now();
  const done = await new Updater(dev2.access).resume(image, null, "FM-1_900");
  ok(done === false && Date.now() - t0 < 6000, "fm1ota.js: unplugged during the write -> stops at once");

  const dev3 = new FakeFM1(image, { unplugAfter: 2 });
  const e = await new Updater(dev3.access).install(image, "FM-1_900").then(() => null, (x) => x);
  ok(e && e.code === "lost", "fm1ota.js: unplugged in step 1 -> error code 'lost'");
  const e2 = await new Updater({ inputs: new Map(), outputs: new Map() }).install(image, "FM-1_900").then(() => null, (x) => x);
  ok(e2 && e2.code === "notfound", "fm1ota.js: no device -> error code 'notfound'");
  /* resume() checks the loader's model against the package, as install() checks the running firmware */
  const smkOta = new FakeFM1(image);
  smkOta.boot("ota-SMK-37 Pro_900", "Felucca Update");
  const m1 = await new Updater(smkOta.access).resume(image, null, "FM-1_900").then(() => null, (x) => x);
  ok(m1 && m1.code === "model" && smkOta.served === 0, "fm1ota.js: an SMK-37 Pro in update mode is never given an FM-1 package ('model')");
  const noPkg = new FakeFM1(image);
  noPkg.boot("ota-FM-1_900", "Felucca Update");
  const m2 = await new Updater(noPkg.access).resume(image).then(() => null, (x) => x);
  ok(m2 && m2.code === "model" && noPkg.served === 0, "fm1ota.js: resume without the package's identity writes nothing");
  const elite = new FakeFM1(image);
  elite.boot("ota-SMK-37 Elite_900", "Felucca Update");
  const r3 = await new Updater(elite.access).resume(image, null, "SMK-37 Pro_900");
  ok(r3 === true && elite.served > 0, "fm1ota.js: resume: the SMK models are one keyboard, as for install()");
}

await packages();
await updater();
console.log(failed ? `WEB TESTS FAILED (${failed})` : "web tests passed");
process.exit(failed ? 1 : 0);

/* SPDX-License-Identifier: GPL-3.0-only */
/* X0X motion: recorded knob moves, one lane per knob per part pattern.
 *
 * A lane holds a value for each step of one part's pattern (MOT_NONE = the knob's own
 * value, "the base"). Lanes live in a pool the project saves; the runtime beside them
 * (what playback last applied, the ramp, the record / hold counters) belongs to the
 * audio ISR alone.
 *
 * Recording writes the steps the knob MOVED on (each turn while recording raises
 * motion_req_rec(); the next step takes the knob's value). A gap of up to MOT_GAP steps
 * between two written steps is filled in a straight line, so a slow sweep has no holes; the
 * steps you did not touch keep what they had. While a gesture lasts (a turn within MOT_GAP
 * steps) the knob, not the lane, is heard.
 *
 * ISR:  motion_step() on every step a part fires, motion_tick() once per block (the ramps
 *       between two set steps), motion_release() when the transport stops.
 * Main: motion_find() / motion_alloc() / motion_clear(), and the two requests
 *       motion_req_rec() (the knob moved, recording) and motion_req_hold() (the knob moved,
 *       not recording: it wins for a pass). Allocation writes the fields first and `used`
 *       last; `gen` tells the ISR a slot was reused, so it resets that slot's runtime. */
#pragma once
#include <stdint.h>
#include "pattern.h"

#define NLANE 160
#define MOT_NONE 0xFFu
#define MOT_PARTS 5
#define MOT_GAP 4                     /* steps: a longer pause ends a recording gesture */

typedef struct {
    uint8_t used, gen;
    uint8_t pat, part;                /* the part pattern it belongs to */
    uint8_t t, v, i;                  /* the parameter (engine.h target, voice, index) */
    uint8_t rsv;
    uint8_t val[NSTEPS];              /* per step, MOT_NONE = the base */
} lane_t;

typedef struct {
    uint8_t gen;                      /* lane gen this runtime belongs to */
    uint8_t applied;                  /* value playback set, MOT_NONE = the engine has the base / knob */
    uint8_t from, to, ramp;           /* the ramp across the current step */
    uint8_t part_parity;              /* parity of the step the ramp started on */
    volatile uint8_t rec_req, hold_req;
    uint8_t rec_last;                 /* the step a gesture last wrote, MOT_NONE = no gesture */
    uint8_t rec_quiet;                /* steps since */
    uint8_t hold_left;                /* steps the knob still wins */
} lane_rt_t;

typedef struct {
    lane_t *lane;                     /* NLANE, the project's */
    lane_rt_t rt[NLANE];
    uint32_t age[MOT_PARTS];          /* samples since the part's last step */
